rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 for name,run in {'profile-avatar-failure-birthday-cancel':profile,'tag-duplicate-transaction-rollback':tag_rollback,'replies-and-notice-preferences':replies_notice,'automatic-backup-save-retry':auto_backup,'member-feedback-failure-persistence':member_feedback,'phone-code-account-delete-retry':account,'drafts-error-motion-setting':drafts_motion,'review-reject-date-failure':review_rejection,'two-factor-gates-login-retry':two_factor}.items():
  c=b.new_context(viewport={'width':390,'height':844});p=c.new_page();p.set_default_timeout(4000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  try:run(p);assert not errors,errors;row={'case':name,'passed':True}
  except Exception as e:row={'case':name,'passed':False,'failure':repr(e)[:1600]}
  row.update(errors=errors,final_url=p.url);rows.append(row);(OUT/'settings-state-results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8');print(row.get('failure',''),flush=True);p.screenshot(path=str(OUT/f'settings-state-{name}.png'),full_page=True);print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True);c.close()
 b.close()
raise SystemExit(0 if all(r['passed'] for r in rows) else 1)
